const prepareAgentSessionForTurn = `-- name: PrepareAgentSessionForTurn :one
UPDATE agent_sessions AS session
SET status = 'active',
    finished_at = NULL,
    updated_at = NOW()
WHERE session.id = $1
  AND session.deleted_at IS NULL
  AND NOT EXISTS (
      SELECT 1
      FROM workflow_runs AS run
      WHERE run.id = session.workflow_run_id
        AND run.status IN ('queued', 'running')
  )
RETURNING session.id, session.repository_id, session.user_id, session.workflow_run_id, session.title, session.status, session.metadata, session.workspace_id, session.started_at, session.finished_at, session.created_at, session.updated_at, session.deleted_at
`

// A completed author session can be resumed for reviewer feedback. Refuse to
// reactivate it while its previous run is still queued/running.
func (q *Queries) PrepareAgentSessionForTurn(ctx context.Context, sessionID string) (AgentSession, error) {
	row := q.db.QueryRow(ctx, prepareAgentSessionForTurn, sessionID)
	var i AgentSession
	err := row.Scan(
		&i.ID,
		&i.RepositoryID,
		&i.UserID,
		&i.WorkflowRunID,
		&i.Title,
		&i.Status,
		&i.Metadata,
		&i.WorkspaceID,
		&i.StartedAt,
		&i.FinishedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.DeletedAt,
	)
	return i, err
}

